const tsrArticlesDB = [
    { id: 1, law: "Устав МО", chapter: "I. Общие положения", point: "1.1", text: "Данный документ является основным документом Федеральной Тюрьмы, обязательным для прочтения.", category: "Устав МО" },
    { id: 2, law: "Устав МО", chapter: "I. Общие положения", point: "1.2", text: "Каждый сотрудник обязан знать, соблюдать и выполнять все пункты описанные в данном документе.", category: "Устав МО" },
    { id: 3, law: "Устав МО", chapter: "I. Общие положения", point: "1.3", text: "Настоящий Устав определяет права и обязанности сотрудников и взаимоотношения между ними, обязанности основных должностных лиц и взводов.", category: "Устав МО" },
    { id: 4, law: "Устав МО", chapter: "I. Общие положения", point: "1.4", text: "Данный уставной документ предписывает для каждого сотрудника наказание за нарушение документа.", category: "Устав МО" },
    { id: 5, law: "Устав МО", chapter: "I. Общие положения", point: "1.5", text: "Незнание данного документа не освобождает никого от ответственности и от наказания.", category: "Устав МО" },
    { id: 6, law: "Устав МО", chapter: "I. Общие положения", point: "1.6", text: "Данный уставной документ может потерпеть изменения в любой момент. (С одобрения следящей администрации).", category: "Устав МО" },
    { id: 7, law: "Устав МО", chapter: "I. Общие положения", point: "1.7", text: "Звания присутствующие в Тюрьме указаны ниже:<ul><li>Охранник [1]</li><li>Конвоир [2]</li><li>Дежурный [3]</li><li>Ст. дежурный [4]</li><li>Надзиратель [5]</li><li>Начальник блока [6]</li><li>Инспектор [7]</li><li>Начальник инспекции [8]</li><li>Зам. Начальника Тюрьмы [9]</li><li>Начальник Тюрьмы [10]</li></ul>", category: "Устав МО" },
    { id: 8, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.1", text: "Сотрудник тюрьмы имеет право открыть огонь по гражданскому лицу в следующих случаях:<ul><li>в случае нападения этого лица на сотрудника или других сотрудников тюрьмы, а также работников других государственных структур;</li><li>в случае если у гражданского лица в руках огнестрельное оружие в пределах любого из военных объектов или охраняемой территории вокруг них;</li><li>в случае отказа этого гражданского лица подчиниться приказу покинуть охраняемую территорию;</li><li>в случае получения соответствующего приказа от офицеров или Начальства.</li></ul>", category: "Устав МО" },
    { id: 9, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.2", text: "Сотрудник тюрьмы имеет право открыть огонь по гражданскому лицу из травматического оружия(весь арсенал который доступен в оружейной), если гражданское лицо отказывается сотрудничать и подчиняться приказам во время проведения призыва новобранцев в Тюрьму на территории любого из военкоматов, а также на прилегающей к военкоматам территорий.(Только в случае, если было нападение с оружием на сотрудника).", category: "Устав МО" },
    { id: 10, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.3", text: "Сотрудник тюрьмы имеет право на отдых в неслужебное время согласно пункту 16 действующего устава, за исключением чрезвычайных ситуаций, или приказа Начальства которые имеют право отменить неслужебное время по своему усмотрению для любого сотрудника тюрьмы.", category: "Устав МО" },
    { id: 11, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.4", text: "Сотрудник тюрьмы имеет право покинуть территорию своего охраняемого объекта в неслужебное время, предварительно сняв форму и сдав табельное оружие на склад.", category: "Устав МО" },
    { id: 12, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.5", text: "Сотрудник тюрьмы имеет право оставлять свое личное транспортное средство в пределах своего охраняемого объекта в местах специально выделенных для этого внутренним распорядком Тюрьмы Строгого Режима.", category: "Устав МО" },
    { id: 13, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.6", text: "Начальство тюрьмы и старший офицерский состав имеют право ставить личные транспортные средства где угодно в пределах своего охраняемого объекта, если это не мешает движению других транспортных средств и работе Тюрьмы в целом.", category: "Устав МО" },
    { id: 14, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.7", text: "Сотрудник тюрьмы имеет право на повышение по службе в специально отведенное для этого время, которое устанавливается внутренним распорядком Тюрьмы.", category: "Устав МО" },
    { id: 15, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.8", text: "Сотрудник тюрьмы имеет право на повышение в звание согласно рапортам о проделанной работе, который ему необходимо разместить в соответствующем разделе на официальном портале Министерства Обороны в том случае, если имеется свободное место на это звание.", category: "Устав МО" },
    { id: 16, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.9", text: "Сотрудник тюрьмы имеет право подать жалобу на имя Начальника , если он считает что другие сотрудники или офицеры Тюрьмы нарушают настоящий Устав. Жалобу можно подать в соответствующем разделе на официальном портале Министерства Обороны.", category: "Устав МО" },
    { id: 17, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.10", text: "Сотрудники стажерского и дежурного состава имеют право покидать территорию своего охраняемого объекта в служебное время только с разрешения старших офицеров, и под присмотром любого офицера, если это не прописано в правилах отвечающих за внутренний распорядок Тюрьмы.", category: "Устав МО" },
    { id: 18, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.11", text: "Сотрудник младшего офицерского состава имеет право отпроситься у Начальства или старших офицеров, с территории своего охраняемого объекта по личным делам на короткое время.", category: "Устав МО" },
    { id: 19, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.12", text: "Все офицеры тюрьмы имеют право передвигаться по территории своей базы на тюремном транспорте, доступном их званию.", category: "Устав МО" },
    { id: 20, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.13", text: "Начальство Тюрьмы и Старшие Офицеры Тюрьмы имеют право в служебных целях покинуть свой охраняемый объект в любое время, а также использовать служебную технику на своё усмотрение.", category: "Устав МО" },

    { id: 21, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.1", text: "Сотрудник обязан соблюдать каждый пункт данного уставного документа, в независимости от занимаемой должности.", category: "Устав МО" },
    { id: 22, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.2", text: "Сотрудник обязан знать свои права, предписанные соответствующими документами.", category: "Устав МО" },
    { id: 23, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.3", text: "Сотрудник обязан соблюдать все действующие пункты устава.", category: "Устав МО" },
    { id: 24, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.4", text: "Сотрудник обязан с честью и доблестью нести свою службу.", category: "Устав МО" },
    { id: 25, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.5", text: "Сотрудник обязан уважать других сотрудников в независимости от их звания.", category: "Устав МО" },
    { id: 26, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.6", text: "Сотрудник обязан исполнять приказы руководящего состава Тюрьмы, а также Начальника Тюрьмы.", category: "Устав МО" },
    { id: 27, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.7", text: "Сотрудник обязан соблюдать субординацию по отношению к другим сотрудникам.", category: "Устав МО" },
    { id: 28, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.8", text: "Сотрудник обязан сообщать в рацию о заступлении на пост, выездах на поставки боеприпасов, о нападении на ВЧ.", category: "Устав МО" },
    { id: 29, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.9", text: "Сотрудник обязан соблюдать пропускной режим министерства обороны.", category: "Устав МО" },
    { id: 30, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.10", text: "Сотрудник обязан соблюдать правила автопарка министерства обороны.", category: "Устав МО" },
    { id: 31, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.11", text: "Сотрудник обязан соблюдать правила проведения призыва в министерстве обороны.", category: "Устав МО" },
    { id: 32, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.12", text: "Сотрудник обязан соблюдать правила поведения в строю.", category: "Устав МО" },
    { id: 33, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.13", text: "Сотрудник обязан носить при себе включенную рацию и соблюдать правила ее использования.", category: "Устав МО" },
    { id: 34, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.14", text: "Сотрудник обязан соблюдать правила поведения на посту.", category: "Устав МО" },
    { id: 35, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.15", text: "Сотрудник обязан охранять территорию тюрьмы и не пропускать на нее представителей преступных группировок, а также гражданских лиц.", category: "Устав МО" },
    { id: 36, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.16", text: "Сотрудник обязан исполнять приказы старшего по званию и руководства взвода, если эти приказы не перечат Уставу.", category: "Устав МО" },
    { id: 37, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.17", text: "Сотрудник обязан подчиняться строго руководящему составу тюрьмы, руководству своего взвода.", category: "Устав МО" },
    { id: 38, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.18", text: "Сотрудник обязан находится в служебной форме на территории Тюрьмы не в отпускное время.", category: "Устав МО" },
    { id: 39, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.19", text: "Сотрудник, охраняющий территорию Федеральной Тюрьмы обязан давать возможность заключенным работать на исправительных работах [Готовить еду | Стирать одежду | Носить ящики | Собирать мусор].", category: "Устав МО" },
    { id: 40, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.20", text: "Сотрудник, охраняющий территорию Федеральной Тюрьмы обязан давать возможность заключенным на выполнение своих нужд.", category: "Устав МО" },
    { id: 41, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.21", text: "Сотрудник имеет право повысить срок заключенному согласно системе повышения срока.", category: "Устав МО" },
    { id: 42, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.22", text: "Сотрудник имеет право перевести заключенного в камеру в случае Чрезвычайной Ситуации или поднятия Бунта.", category: "Устав МО" },
    { id: 43, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.23", text: "Сотрудник Федеральной Тюрьмы обязан следить за порядком на территории тюрьмы.", category: "Устав МО" },
    { id: 44, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.24", text: "Сотрудник имеет полное право на обыск заключенного.", category: "Устав МО" },
    { id: 45, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.25", text: "Сотрудник обязан общаться с заключенными соблюдая субординацию в любой ситуации.", category: "Устав МО" },

    { id: 46, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.1", text: "Запрещено сотруднику нарушать данный уставной документ.", category: "Устав МО" },
    { id: 47, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.2", text: "Запрещено сотруднику нарушать ЕФК. ФП а также УК.", category: "Устав МО" },
    { id: 48, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.3", text: "Запрещено сотруднику заниматься криминальной деятельностью, а также сотрудничать с нарушителями закона которые являются членами преступных группировок.", category: "Устав МО" },
    { id: 49, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.4", text: "Запрещено сотруднику самовольно покидать базу без ведома старшего состава тюрьмы, либо Начальства.", category: "Устав МО" },
    { id: 50, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.5", text: "Запрещено сотруднику игнорировать приказы руководящего состава тюрьмы.", category: "Устав МО" },
    { id: 51, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.6", text: "Запрещено сотруднику унижать честь и достоинство любого гражданина штата.", category: "Устав МО" },
    { id: 52, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.7", text: "Запрещено сотруднику злоупотреблять служебными полномочиями.", category: "Устав МО" },
    { id: 53, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.8", text: "Запрещено сотруднику выпрашивать повышение, премию, либо намекать на те или иные действия.", category: "Устав МО" },
    { id: 54, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.9", text: "Запрещено сотруднику производить выстрелы из огнестрельного оружия без весомой причины.", category: "Устав МО" },
    { id: 55, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.10", text: "Запрещено сотруднику не появляться на рабочем месте более десяти дней, при этом не находясь в отпуске.", category: "Устав МО" },
    { id: 56, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.11", text: "Запрещено сотруднику обманывать, либо вводить в заблуждение весь состав Министерства Обороны.", category: "Устав МО" },
    { id: 57, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.12", text: "Запрещено сотруднику находится на территории тюрьмы без бронежилета на теле не в отпускное время, исключением является старший офицерский состав.", category: "Устав МО" },
    { id: 58, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.13", text: "Запрещено сотруднику в одиночку перевозить боеприпасы в отделения полицейских департаментов. Исключение: Ночное время с 23:00 до 9:00 и при условии что склад Департамента МЮ не полный.", category: "Устав МО" },
    { id: 59, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.14", text: "Запрещено сотруднику спать в интерьере в рабочее и не рабочее время. (Разрешено стоять в АФК в: a) Личный дом/квартира; b) Семейная квартира; c) Арендованные комнаты; d) Отели; e) Трейлеры; f) Личные транспортные средства с интерьером (Enforcer, Boxville и т.п.); g) Стрип-клуб; h) Подземные паркинги. i) Больницы штата.", category: "Устав МО" },
    { id: 60, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.15", text: "Запрещено сотруднику вести общение по волне департамента до звания Начальник Блока[6].", category: "Устав МО" },
    { id: 61, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.16", text: "Запрещено сотруднику самовольно переходить в другие взводы.", category: "Устав МО" },
    { id: 62, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.17", text: "Запрещено использовать личное ТС на службе. (Исключение: 8-10 ранги).", category: "Устав МО" },
    { id: 63, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.18", text: "Запрещено сотруднику носить предметы, скрывающие лицо(маски). Исключение: во время ЧС на Территории Тюрьмы.", category: "Устав МО" },
    { id: 64, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.19", text: "Сотрудник не имеет право оскорблять заключенных, провоцировать на конфликт, неадекватно ввести себя, применять физическую силу без весомых причин.", category: "Устав МО" },
    { id: 65, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.20", text: "Сотруднику запрещено помогать заключенным в совершении подозрительных действий.", category: "Устав МО" },
    { id: 66, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.21", text: "Сотруднику запрещено нарушать Устав ФТ, Систему повышения срока.", category: "Устав МО" },

    { id: 67, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.1", text: "Стажерским составом считаются сотрудники тюрьмы со звания Охранник [1] до звания Конвоир [2] включительно.", category: "Устав МО" },
    { id: 68, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.2", text: "Дежурным составом считаются сотрудники тюрьмы со звания Дежурный[3] до звания Ст. Дежурный[4] включительно.", category: "Устав МО" },
    { id: 69, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.3", text: "Младшим офицерским составом считаются сотрудники тюрьмы со звания Надзиратель[5] до звания Начальник блока[6] включительно.", category: "Устав МО" },
    { id: 70, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.4", text: "Старшим офицерским составом считаются сотрудники тюрьмы со звания Инспектор[7] до звания Начальник инспекции[8] включительно.", category: "Устав МО" },
    { id: 71, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.5", text: "Начальник/Зам. Начальника тюрьмы являются высшими офицерами и непосредственно отвечают за работу Тюрьмы, обучение, воспитание и повседневную деятельность состава.", category: "Устав МО" },

    { id: 72, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.1", text: "В любое время суток на территорию Тюрьмы Строгого Режима, не допускаются гражданские лица, или лица из других государственных структур, без особого разрешения.", category: "Устав МО" },
    { id: 73, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.2", text: "Вход в воздушное пространство над территорией любого из охраняемых объектов без разрешения возможен только для представителей министерства юстиции и только в случаях чрезвычайной ситуации, в остальных случаях нарушения воздушного пространства сотрудники имеют право открыть огонь на поражение без предупреждения.", category: "Устав МО" },
    { id: 74, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.3", text: "Особое разрешение на посещение территории, а также разрешение на вход в воздушное пространство охраняемого объекта, могут быть выданы только Начальством тюрьмы и старшим офицерским составом на данном охраняемом объекте, или старшим по званию командующим офицером охраняемого объекта, находящимся в Штате в этот момент.", category: "Устав МО" },
    { id: 75, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.4", text: "Губернатор штата, директор РО ФБР и их заместители могут находиться на охраняемых объектах по предъявлению документов: 1) Иные лица не имеют право находиться на охраняемых объектах, исключением является разрешение со стороны командования Тюрьмы; 2) Иные сотрудники РО ФБР могут находиться на территории охраняемых объектов только в тех случаях, если агенты ведут оперативно-следственную деятельность, при предъявлении документов с сопровождением старшего офицера. Все выше перечислены должностные лица должны соблюдать и выполнять требования указанные в пункте 6.2. данного уставного акта для пересечения воздушного пространства любого охраняемого объекта находящегося в штате.", category: "Устав МО" },

    { id: 76, law: "Устав МО", chapter: "VII. Правила постов", point: "7.1", text: "Сотрудник при заступление на пост обязан иметь хорошее самочувствие и не иметь чувства голода.", category: "Устав МО" },
    { id: 77, law: "Устав МО", chapter: "VII. Правила постов", point: "7.2", text: "Сотрудник при заступление на пост обязан иметь при себе необходимое вооружение [Бронежилет, M4, Desert Eagle] и необходимое количество боеприпасов.", category: "Устав МО" },
    { id: 78, law: "Устав МО", chapter: "VII. Правила постов", point: "7.3", text: "Сотрудник при заступление на пост обязан сообщить в рацию.", category: "Устав МО" },
    { id: 79, law: "Устав МО", chapter: "VII. Правила постов", point: "7.4", text: "Сотруднику запрещено спать или дремать на посту.", category: "Устав МО" },
    { id: 80, law: "Устав МО", chapter: "VII. Правила постов", point: "7.5", text: "Сотрудник обязан осуществлять доклад с поста каждые 10 минут.", category: "Устав МО" },
    { id: 81, law: "Устав МО", chapter: "VII. Правила постов", point: "7.6", text: "Сотрудник обязан сообщить о покидание поста.", category: "Устав МО" },
    { id: 82, law: "Устав МО", chapter: "VII. Правила постов", point: "7.7", text: "Форма доклада: Заступление на пост /r Докладывает Звание Фамилия, заступил на пост: (Указать пост). Доклад с поста /r Доклад: Докладывает Звание Фамилия, нахожусь на посту: (Указать пост), состояние: (ЧС/Спокойно/Нападение). Покидание поста /r Докладывает Звание Фамилия, покидаю пост: (Указать пост) последнее состояние: (ЧС/Спокойно/Нападение).", category: "Устав МО" },
    { id: 83, law: "Устав МО", chapter: "VII. Правила постов", point: "7.8", text: "Чтобы заступить на пост, нужно занять его. (N на посту).", category: "Устав МО" },

    { id: 84, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.1", text: "Пропуск на территорию осуществляется с согласия всех сторон, а именно лиц желающих посетить территорию тюрьмы по особо важному вопросу и одобрению на посещение со стороны лиц офицерского состава Тюрьмы с учетом раннего предупреждения о прибытии.", category: "Устав МО" },
    { id: 85, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.2", text: "Нарушение воздушного/сухопутного/водного пространства охраняемой территории, разрешено только с разрешения офицерского состава, а именно того лица, который в данный момент суток является старшим по званию, находящимся на территории.", category: "Устав МО" },
    { id: 86, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.3", text: "Нарушение любого территориального пространства охраняемой территории без разрешения старших по званию подлежат немедленной ликвидации. Исключение см. в пункте 6.4 данного уставного акта.", category: "Устав МО" },
    { id: 87, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.4", text: "При проникновение через КПП в светлое время суток нарушителя следует предупредить о проникновении на охраняемую территорию, попросить покинуть объект и в случае неповиновения применить силы для ликвидации нарушителя.", category: "Устав МО" },

    { id: 88, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.1", text: "Служебная форма одежды является неотъемлемым атрибутом службы, определяющим принадлежность сотрудников к Министерству Обороны.", category: "Устав МО" },
    { id: 89, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.2", text: "Форма сотрудника всегда должна быть целого состояние и приемлемого вида", category: "Устав МО" },
    { id: 90, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.3", text: "Служебная форма одежды подразделяется по категориям, в зависимости от звания.", category: "Устав МО" },
    { id: 91, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.4", text: "Сотрудник обязан носить форму согласно своему званию.", category: "Устав МО" },
    { id: 92, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.5", text: "Сотруднику запрещено носить кейс с деньгами. (Исключение 9-10 ранг).", category: "Устав МО" },
    { id: 93, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.6", text: "Сотруднику разрешено носить: армейский берет, армейскую каску, респиратор, часы, тактические наушники, бронежилет, прозрачные и солнцезащитные очки в черной оправе, монокль, повязку на глаз, платок на шею, прибор ночного видения (после 21:00 и до 7:00), попугай, машинка на п/у, сердце на грудь, доллар на грудь, ключ на грудь, замок на грудь, череп на грудь, неяркую шапку, щит на спину любого цвета, гитару, крестик на грудь, фотоаппарат на грудь, патрон на грудь, звезду шерифа на грудь, усы, борода, золотые погоны, полицейская фуражка, Desert Eagle, АК-47, M4, тактический шлем, золотой Desert Eagle, обрезы, пояс с боеприпасами, полицейский пояс, граната «Advance», длинный Desert Eagle, Военный рюкзак, Связка гранат, Траншейная лопата. Новый сет военного", category: "Устав МО" },
    { id: 94, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.7", text: "Все остальные аксессуары, не указанные в пункте 9.6, запрещено носить в рабочее время и в форме, за их ношение вы будете привлечены к ответственности руководством Тюрьмы. (Подробнее о форме одежде можно узнать в разделе F.A.Q. по Министерству Обороны).", category: "Устав МО" },

    { id: 95, law: "Устав МО", chapter: "X. Субординация", point: "10.1", text: "Сотрудники должны постоянно служить примером высокой культуры, скромности и выдержанности.", category: "Устав МО" },
    { id: 96, law: "Устав МО", chapter: "X. Субординация", point: "10.2", text: "Взаимоотношения между сотрудниками строятся на основе взаимного уважения.", category: "Устав МО" },
    { id: 97, law: "Устав МО", chapter: "X. Субординация", point: "10.3", text: "По вопросам службы сотрудники должны обращаться друг к другу на \"Вы\" и последующей форме: Звание Фамилия Пример: \"Начальник Тёрнер, разрешите обратиться?\"", category: "Устав МО" },
    { id: 98, law: "Устав МО", chapter: "X. Субординация", point: "10.4", text: "Искажение тюремных званий, употребление нецензурных слов, кличек и прозвищ, грубость несовместимы с понятием достоинства сотрудника.", category: "Устав МО" },
    { id: 99, law: "Устав МО", chapter: "X. Субординация", point: "10.5", text: "Вне строя, отдавая или получая приказ, сотрудники обязаны принять строевую стойку.", category: "Устав МО" },
    { id: 100, law: "Устав МО", chapter: "X. Субординация", point: "10.6", text: "При обращении к другому сотруднику в присутствии командира [старшего по званию] у него необходимо спросить на это разрешение.", category: "Устав МО" },
    { id: 101, law: "Устав МО", chapter: "X. Субординация", point: "10.7", text: "Если при встрече нельзя свободно разойтись с старшим по званию, сотрудник обязан уступить дорогу и, приветствуя, пропустить его; при необходимости обогнать старшего по званию, сотрудник должен спросить на то разрешение.", category: "Устав МО" },
    { id: 102, law: "Устав МО", chapter: "X. Субординация", point: "10.8", text: "Сотрудники должны быть вежливыми по отношению к гражданскому населению, проявлять особое внимание к инвалидам, пожилым людям, женщинам и детям.", category: "Устав МО" },
    { id: 103, law: "Устав МО", chapter: "X. Субординация", point: "10.9", text: "Сотрудникам запрещается держать руки в карманах одежды, сидеть или курить в присутствии старшего по званию без его разрешения.", category: "Устав МО" },
    { id: 104, law: "Устав МО", chapter: "X. Субординация", point: "10.10", text: "Трезвый образ жизни должен быть повседневной нормой поведения всех сотрудников.", category: "Устав МО" },
    { id: 105, law: "Устав МО", chapter: "X. Субординация", point: "10.11", text: "Правила служебной вежливости, поведения и выполнения приветствия обязательны также для граждан, уволенных со службы, при ношении ими служебной формы одежды.", category: "Устав МО" },

    { id: 106, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.1", text: "Служебная Рация предусмотрена для связи между сотрудниками.", category: "Устав МО" },
    { id: 107, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.2", text: "Рацией разрешено пользоваться строго в служебных целях.", category: "Устав МО" },
    { id: 108, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.3", text: "Запрещено использовать рацию для покупки, продажи и рекламы имущества.", category: "Устав МО" },
    { id: 109, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.4", text: "Запрещено использовать при разговорах по рации брань, ругань и оскорбления сотрудников.", category: "Устав МО" },
    { id: 110, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.5", text: "Запрещено сотруднику создавать помехи в общении по рации.", category: "Устав МО" },
    { id: 111, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.6", text: "Сотрудник обязан вести общение по рации с указанием своего отряда.", category: "Устав МО" },
    { id: 112, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.7", text: "Сотрудник обязан вести общение по рации с другими сотрудниками исключительно в уважительной форме.", category: "Устав МО" },
    { id: 113, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.8", text: "При общение в рации не используются не системные тэги. [Только те, что устанавливают лидер/заместители через /settag]", category: "Устав МО" },

    { id: 114, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.1", text: "Командир обязан указать место, время, порядок построения, форму одежды и снаряжение, а также какое иметь вооружение и служебную технику; при необходимости назначить наблюдателя;", category: "Устав МО" },
    { id: 115, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.2", text: "Командир обязан проверить и знать наличие в строю подчиненных своего взвода, а также вооружения, служебной техники, боеприпасов, средств индивидуальной защиты;", category: "Устав МО" },
    { id: 116, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.3", text: "Командир обязан проверить внешний вид подчиненных, а также наличие снаряжения и правильность его подготовки;", category: "Устав МО" },
    { id: 117, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.4", text: "Командир обязан поддерживать дисциплину строя и требовать точного выполнения подразделениями команд и сигналов, а сотрудниками своих обязанностей в строю;", category: "Устав МО" },
    { id: 118, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.5", text: "Командир обязан при построении подразделений с вооружением и служебной техникой произвести внешний осмотр их, а также проверить наличие и исправность оборудования для перевозки личного состава.", category: "Устав МО" },
    { id: 119, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.1", text: "Сотрудник обязан вовремя явиться в строй.", category: "Устав МО" },
    { id: 120, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.2", text: "Сотрудник обязан проверить исправность своего оружия, закрепленных за ним вооружения и служебной техники, боеприпасов, средств индивидуальной защиты, обмундирования и снаряжения;", category: "Устав МО" },
    { id: 121, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.3", text: "Сотрудник обязан аккуратно заправить обмундирование, правильно надеть и подогнать снаряжение, помочь товарищу устранить замеченные недостатки;", category: "Устав МО" },
    { id: 122, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.4", text: "Сотрудник обязан знать свое место в строю, уметь быстро, без суеты занять его; в движении сохранять равнение, установленные интервал и дистанцию; соблюдать требования безопасности; не выходить из строя [машины] без разрешения;", category: "Устав МО" },
    { id: 123, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.5", text: "В строю без разрешения не разговаривать и не курить, не использовать сотовые телефоны; быть внимательным к приказаниям и командам своего командира, быстро и точно их выполнять, не мешая другим;", category: "Устав МО" },
    { id: 124, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.6", text: "В строю не держать в руках оружия, если на то не было команды;", category: "Устав МО" },
    { id: 125, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.7", text: "Передавать приказания, команды без искажений, громко и четко.", category: "Устав МО" },

    { id: 126, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.1", text: "Сотрудникам допускается использование служебного транспорта только в целях исполнения обязанностей.", category: "Устав МО" },
    { id: 127, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.2", text: "Стажерскому составу допускается использование служебного транспорта, таких как Фуры", category: "Устав МО" },
    { id: 128, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.3", text: "Дежурному составу с разрешения офицерского состава допускается использование: Фур, Автобусов, Хаммеров, Каргобобов.", category: "Устав МО" },
    { id: 129, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.4", text: "Младшему офицерскому составу допускается использование: Фур, Автобусов, Хаммеров, Каргобобов.", category: "Устав МО" },
    { id: 130, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.5", text: "Старшему офицерскому составу допускается использование всего имеющегося транспорта.", category: "Устав МО" },

    { id: 131, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.1", text: "На призыве должен присутствовать офицер управляющий призывом - Зам. Начальника/Начальник тюрьмы.", category: "Устав МО" },
    { id: 132, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.2", text: "Управляющий обязан сообщить о предстоящем призыве офицерам за 15 минут до начала, а также решить, кто будет задействован.", category: "Устав МО" },
    { id: 133, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.3", text: "Сотрудники, задействованные в проведение призыва, должны находиться на КПП за 5 минут до начала призыва.", category: "Устав МО" },
    { id: 134, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.4", text: "Оканчивать призыв разрешается только через час после его начала.", category: "Устав МО" },
    { id: 135, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.5", text: "После окончания призыва для новобранцев должна быть проведена экскурсия по территории и лекция.", category: "Устав МО" },
    { id: 136, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.6", text: "Сон во время призыва строго запрещен. (Афк не более 1 минуты).", category: "Устав МО" },
    { id: 137, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.7", text: "В случаях, когда управляющему призывом (Зам. Начальника/Начальнику) необходимо отлучиться или когда управляющий за несколько минут до призыва по весомым причинам не может явиться на призыв, управляющий в праве назначить любого сотрудника из старшего офицерского состава для помощи на призыве. Управляющему необходимо вернуться в течение 5 минут.", category: "Устав МО" },

    { id: 138, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.1", text: "С 5 на 6 ранг - 2 дня на должности", category: "Устав МО" },
    { id: 139, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.2", text: "С 6 на 7 ранг - 4 дня на должности", category: "Устав МО" },
    { id: 140, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.3", text: "С 7 на 8 ранг - 5 дней на должности", category: "Устав МО" },
    { id: 141, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.4", text: "С 8 на 9 ранг - 7 дней на должности", category: "Устав МО" },
    { id: 142, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.5", text: "9 ранг для увольнения без варна - 15 дней на должности", category: "Устав МО" },

    { id: 143, law: "Устав МО", chapter: "XVI. График рабочего дня", point: "16.1", text: "Сотрудники несут службу каждый день недели (понедельник - воскресенье). Рабочий день начинается в 10:00 и заканчивается в 21:30.", category: "Устав МО" },
    { id: 144, law: "Устав МО", chapter: "XVI. График рабочего дня", point: "16.2", text: "Сотрудник обязан сдать форму, перед уходом в увольнительное время.", category: "Устав МО" },
    { id: 145, law: "Устав МО", chapter: "XVI. График рабочего дня", point: "16.3", text: "У каждого сотрудника начиная с ранга [1] имеется обеденный перерыв с 14:00 до 16:00, это время приравнивается к увольнительному.", category: "Устав МО" },

    { id: 146, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.1", text: "Взятие отпуска разрешается только с звания Надзиратель[5].", category: "Устав МО" },
    { id: 147, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.2", text: "Минимально допустимый отпуск - 1 день.", category: "Устав МО" },
    { id: 148, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.3.1", text: "Со звания Надзиратель[5] до звания Зам. Начальника[9] - 7 дней.", category: "Устав МО" },
    { id: 149, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.3.2", text: "С звания Начальник[10] - 3 дня.", category: "Устав МО" },
    { id: 150, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.4", text: "Перед уходом в отпуск сотрудник обязан отработать на должности не менее, чем его испытательный срок на звании.", category: "Устав МО" },
    { id: 151, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.5", text: "Перед уходом в отпуск любой сотрудник обязан заполнить заявление на отпуск в специальной теме.", category: "Устав МО" },
    { id: 152, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.6", text: "Отправлять в отпуск [увольнять] может только руководящий состав.", category: "Устав МО" },
    { id: 153, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.7", text: "Если сотрудник имеет выговоры, то в отпуск он уйти не может.", category: "Устав МО" },

    { id: 154, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.1", text: "Министерство обороны и министерство юстиции обязуются между собой проводить совместные учения, участвовать в совместной обороне штата и его граждан в случае необходимости.", category: "Устав МО" },
    { id: 155, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.2", text: "Министерство обороны обязуется ежедневно поставлять боеприпасы в департаменты министерства юстиции. Министерство обороны обязуются прекратить поставки боеприпасов в случае, если данное распоряжение поступит от губернатора штата.", category: "Устав МО" },
    { id: 156, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.3", text: "Сотрудникам полицейских департаментов запрещено задерживать сотрудников тюрьмы в форме на территории. Для этого им необходимо связаться с сотрудниками Федерального Бюро Расследований.(Искл. Если он заехал специально на ВЧ)", category: "Устав МО" },
    { id: 157, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.4", text: "Сотрудники тюрьмы обязуются задержать сотрудника департамента министерства юстиции в случае, если тот нарушит правило нахождения на территории Тюрьмы , прописанное в уставе министерства обороны. Применение огнестрельного оружия разрешается лишь в случае, если жизни сотрудника тюрьмы угрожает опасность.", category: "Устав МО" },
    { id: 158, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.5", text: "По окончанию устранения чрезвычайной ситуации, сотрудники департаментов министерства юстиции в праве находится на охраняемом объекте в течении 15 минут. Далее - только с разрешением командования тюрьмы.", category: "Устав МО" },
    { id: 159, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.6", text: "Проведение агитаций между министерствами проводятся по обоюдному согласию двух сторон. Агитационные мероприятия разрешается проводить максимум раз в день.", category: "Устав МО" },
    { id: 160, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.7", text: "Федеральное Бюро Расследований в праве задерживать сотрудников в форме на территории Тюрьмы, в случае если они находятся в федеральном розыске, для допроса. При этом допрос должен проходить с офицерским составом Тюрьмы(7-10). За несоблюдение 19 раздела устава ТСР, сотрудники Тюрьмы могут получить наказание в виде выговора/увольнения.", category: "Устав МО" },

    { id: 161, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.1", text: "Внутренний устав взвода является приложением к Единому уставу министерства обороны, обязательным для соблюдения всеми сотрудниками, состоящем в данном взводе.", category: "Устав МО" },
    { id: 162, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.2", text: "Незнание данного документа не освобождает никого от ответственности и от наказания.", category: "Устав МО" },
    { id: 163, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.3", text: "Данный уставной документ можете потерпеть изменения в любой момент. [С одобрения следящей администрации].", category: "Устав МО" },
    { id: 164, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.4", text: "Код подразделения (Тэг) - [ВОиС]", category: "Устав МО" },
    { id: 165, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.1", text: "Сотрудник взвода имеет право на остановку сотрудника, покидающего военную базу, без разрешения старшего офицерского состава.", category: "Устав МО" },
    { id: 166, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.2", text: "Сотрудник взвода имеет право остановить военнослужащего, использующего служебный транспорт, не соответствующий его званию, либо личное транспортное средство в нарушение установленного порядка. [Исключение: военнослужащие ВП].", category: "Устав МО" },
    { id: 167, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.3", text: "Сотрудник взвода имеет право потребовать у военнослужащего объяснить причину открытия огня, если нарушение или угроза, послужившие основанием для открытия огня, не были очевидны.", category: "Устав МО" },
    { id: 168, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.4", text: "Если на КПП присутствует представители других гос. структур Сотрудник данного взвода имеет право: > Потребовать удостоверение и цель прибытия вне зависимости от его секретности. > Попросить покинуть территорию охраняемой территории, либо же прилегающую территорию, если у предъявившего документа не имеется на то разрешения от старшего офицерского состава.", category: "Устав МО" },
    { id: 169, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.6", text: "Сотрудник взвода имеет право открыть огонь на поражение в случае, если нарушитель оказывает вооружённое сопротивление, представляет непосредственную угрозу жизни или здоровью военнослужащих либо иных лиц, либо отказывается покинуть охраняемую территорию после установленного предупреждения. [Сделав 3 предупредительных выстрела в воздух].", category: "Устав МО" },
    { id: 170, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.7", text: "Сотрудник взвода имеет право отступать от требований ПДД исключительно при выполнении служебной задачи и включённом специальном сигнале, если это необходимо для её выполнения и не создаёт необоснованной угрозы другим участникам движения.", category: "Устав МО" },
    { id: 171, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.8", text: "В случае нападения на служебную фуру сотрудник ВОиС вправе временно не выполнять требования сотрудников МЮ, если их выполнение препятствует отражению нападения или создаёт угрозу жизни и здоровью военнослужащих.", category: "Устав МО" },
    { id: 172, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.9", text: "Сотрудник взвода имеет право при нападении на фуру в городе или в сельской местности начинать оборону с огнестрельного оружия, не оказывая угрозы гражданам штата.", category: "Устав МО" },
    { id: 173, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.10", text: "Сотрудник взвода имеет право идти на таран при нападение и попытке спровоцировать ДТП.", category: "Устав МО" },
    { id: 174, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.11", text: "Сотрудник взвода имеет право запрашивать фуры и боеприпасы у другой армии.", category: "Устав МО" },
    { id: 175, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.12", text: "Сотрудник взвода имеет право выполнять поставки не на ваши объекты поставок при прямом запросе от этих объектов или другой армии.", category: "Устав МО" },
    { id: 176, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.13", text: "Сотрудник взвода имеет право запрашивать сопровождение от МЮ при поставках.", category: "Устав МО" },
    { id: 177, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.14", text: "Сотрудник взвода имеет право останавливаться на заправках в случае крайней необходимости.", category: "Устав МО" },
    { id: 178, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.1", text: "Сотруднику взвода запрещено находиться на посту не в полном боекомплекте. [Отсутствие Бронежилета/Оружия].", category: "Устав МО" },
    { id: 179, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.2", text: "Сотруднику взвода запрещено находиться на пост в нездоровом виде. [Менее 50% хп].", category: "Устав МО" },
    { id: 180, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.3", text: "Сотруднику взвода запрещено не осуществлять проверку документов у вновь прибывших лиц, не являющихся сотрудниками вашего охраняемого объекта.", category: "Устав МО" },
    { id: 181, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.4", text: "Сотруднику взвода запрещено открывать огонь в дневное время суток без предупреждения гражданского лица.", category: "Устав МО" },
    { id: 182, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.5", text: "Сотруднику взвода запрещено выпускать с территории военной базы военнослужащих без соответствующего разрешения, за исключением военнослужащих старшего и высшего офицерского состава. [с 7 по 10 порядкового звания]", category: "Устав МО" },
    { id: 183, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.6", text: "Сотруднику взвода запрещено использовать оружие в случаях не предусмотренных уставом.", category: "Устав МО" },
    { id: 184, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.7", text: "Сотруднику взвода запрещено не осуществлять доклад в рацию о заступление на пост/по кидание поста.", category: "Устав МО" },
    { id: 185, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.8", text: "Сотруднику взвода запрещено игнорировать работу в цеху.", category: "Устав МО" },
    { id: 186, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.9", text: "Сотруднику взвода запрещено продавать/хранить боеприпасы.", category: "Устав МО" },
    { id: 187, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.10", text: "Сотруднику взвода запрещено выезжать на поставку без доклада в рацию и одобрения старшего состава ВОиС либо ответственного за поставки военнослужащего. Примеры доклада: /r Доклад: Загружаюсь на складе и выезжаю в полицейский департамент ЛСПД/СФПД/РКШД/ЛВПД/ФБР. /r Доклад: Разгружаюсь на складе ЛСПД/СФПД/РКШД/ЛВПД/ФБР. Возвращаюсь на базу.", category: "Устав МО" },
    { id: 188, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.11", text: "Сотруднику взвода запрещено делать поставки не по маршрутам.", category: "Устав МО" },
    { id: 189, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.12", text: "Сотруднику взвода запрещено покидать служебный транспорт при остановке сотрудниками МЮ без соответствующего требования или необходимости. Исключение: нападение на транспортное средство либо возникновение непосредственной угрозы жизни и здоровью.", category: "Устав МО" },
    { id: 190, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.13", text: "Сотруднику взвода запрещено включать спец. сигналы без весомой на то причины.", category: "Устав МО" },
    { id: 191, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.14", text: "Сотруднику взвода запрещено игнорировать остановку от сотрудников МЮ при езде без спец. сигнала.", category: "Устав МО" },
    { id: 192, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.15", text: "Сотруднику взвода запрещено не блокировать двери при остановке от сотрудников МЮ. [/jlock]", category: "Устав МО" },
    { id: 193, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.16", text: "Сотруднику взвода запрещено при поставках выполнять просьбы от гражданских независимо от ситуации.", category: "Устав МО" },
    { id: 194, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.17", text: "Сотруднику взвода запрещено игнорировать требования постового об остановке при въезде или выезде с военной базы вне зависимости от его звания.", category: "Устав МО" },
    { id: 195, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.18", text: "Сотруднику взвода запрещено открывать огонь без предупреждения в случае тарана.", category: "Устав МО" },

    { id: 196, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.1", text: "Внутренний устав взвода является приложением к Единому уставу министерства обороны, обязательным для соблюдения всеми военнослужащими, состоящем в данном взводе.", category: "Устав МО" },
    { id: 197, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.2", text: "Незнание данного документа не освобождает никого от ответственности и от наказания.", category: "Устав МО" },
    { id: 198, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.3", text: "Данный уставной документ можете потерпеть изменения в любой момент. [С одобрения следящей администрации].", category: "Устав МО" },
    { id: 199, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.4", text: "Код подразделения (Тэг) - [ВОН]", category: "Устав МО" },
    { id: 200, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.1", text: "Военнослужащий взвода имеет право поддерживать субординацию, дисциплину, тем самым показывать пример в расположении и другим военнослужащим.", category: "Устав МО" },
    { id: 201, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.2", text: "Военнослужащий взвода имеет право на обучение будущих офицеров армии, их подготовку как в плане физических, так и интеллектуальных навыков, развивая их во всех военных направлениях.", category: "Устав МО" },
    { id: 202, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.3", text: "Военнослужащий взвода имеет право проводить тренировки для младшего состава армии, чтобы укрепить их теоретические и практические знания полученные входе прохождения службы.", category: "Устав МО" },
    { id: 203, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.4", text: "Военнослужащий взвода имеет право на проведение специальных и общих лекций, экскурсий военнослужащим.", category: "Устав МО" },
    { id: 204, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.5", text: "Военнослужащий взвода имеет право командовать всем младшим составом, для их дальнейшего обучения и выполнения ими прямых приказов и обязанностей.", category: "Устав МО" },
    { id: 205, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.6", text: "Военнослужащий взвода имеет право оказывать помощь другим взводам в вопросах, связанных с его компетенцией и обязанностями, при отсутствии противоречий с распоряжениями руководства армии.", category: "Устав МО" },
    { id: 206, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.7", text: "Военнослужащий взвода имеет право принимать специальные нормативы для повышения навыков военнослужащего и его дальнейшего повышения в звании, такие как: курс офицерской подготовки [КОП].", category: "Устав МО" },
    { id: 207, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.8", text: "Военнослужащий взвода имеет право выдавать наказания, как устные так и письменные с занесением в личное дело военнослужащего [Просить выговор военнослужащему], в случаи невыполнения его приказов и приказов других офицеров, устава министерства обороны.", category: "Устав МО" },
    { id: 208, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.9", text: "Военнослужащий взвода имеет право присутствовать на призыве и проводить отбор новобранцев в министерство обороны, для дальнейшего обучения военнослужащих.", category: "Устав МО" },
    { id: 209, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.1", text: "Военнослужащему взвода запрещено выдавать необоснованные наказания для военнослужащих.", category: "Устав МО" },
    { id: 210, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.2", text: "Военнослужащему взвода запрещено вести себя неподобающе офицеру, общаться грубо, оскорбительно, задевать честь и достоинство военнослужащих своего взвода и армии.", category: "Устав МО" },
    { id: 211, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.3", text: "Военнослужащему взвода запрещено выезжать с территории базы на тренировки, другие мероприятия связанные напрямую с деятельностью армии, без предупреждения старшего офицера на базе, если такого не имеется, то данный офицер должен оставить пометку в журнале тренировок и выезда с базы. Примеры доклада: /r Прошу разрешения для проведения выездной тренировки, с последующей транспортировкой военнослужащих вместо проведения тренировки. /r Прошу разрешения для выезда с базы автобуса, по причине: тренировка младшего состава.", category: "Устав МО" },
    { id: 212, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.4", text: "Военнослужащему взвода запрещено командовать военнослужащими других взводов, если поступил такой приказ от непосредственно командира взвода.", category: "Устав МО" },
    { id: 213, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.5", text: "Военнослужащему взвода запрещено находясь в отпуске, гражданской форме, порочить честь и достоинство своего взвода, так и себя самого, подставляя тем самым адмирала армии и его заместителей.", category: "Устав МО" },
    { id: 214, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.6", text: "Военнослужащему взвода запрещено проводить построения, лекции, тренировки, если был дан другой приказ от старшего офицера армии.", category: "Устав МО" },
    { id: 215, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.7", text: "Военнослужащему взвода запрещено игнорировать военнослужащих желающих пройти курс подготовки офицеров [КОП], сдать или пересдать устав, а так же принять присягу министерству обороны.", category: "Устав МО" },
    { id: 216, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.8", text: "Военнослужащему взвода запрещено проводить мероприятия, описанные в пункте 3.7., без фиксации выполненной работы со стороны принимающего их военнослужащего.", category: "Устав МО" },
    { id: 217, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.9", text: "Военнослужащему взвода запрещено быть некомпетентным в вопросах знания устава, присяги, специальных или общих лекций, тренировок проводимых для военнослужащих.[Обязаны знать большое число лекций и возможных тренировок, а не проводить одно и то же].", category: "Устав МО" },
    { id: 218, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.10", text: "Военнослужащему взвода запрещено игнорировать приказы и поручения командира взвода, если на то нет веской причины, которая не идёт в разрез с уставом министерства обороны.", category: "Устав МО" },
    { id: 219, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.11", text: "Военнослужащему взвода запрещено предоставлять военнослужащим и иным лицам заведомо ложную или недостоверную информацию об армии, правилах прохождения службы, тренировках, лекциях и иных мероприятиях.", category: "Устав МО" },

    { id: 220, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "1", text: "Задача ВОиС обеспечить полноценность и неисчерпаемость склада армии. Правила вступают в силу с даты ее публикации. За грубое нарушение в поставках боеприпасов будет получать командир Взвода Охраны и Снабжения так же проводиться беседа с лидером.", category: "Устав МО" },
    { id: 221, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "2.1", text: "Колонна должна состоять минимум из 2х фур.", category: "Устав МО" },
    { id: 222, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "2.2", text: "Формирование колонны происходит: Для армии Лос-Сантос у КПП - 1, либо КПП - 2; Для армии Сан-Фиерро у КПП - 1; Для ТСР у КПП - 12.", category: "Устав МО" },
    { id: 223, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "2.3", text: "Разрешено проводить только одну поставку в час по 4 фуры для каждой армии.", category: "Устав МО" },
    { id: 224, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.1", text: "Хаммер или Камаз(без лишнего тюнинга, максимально разрешается 1 отбойник). Ведущая машина с охраной.", category: "Устав МО" },
    { id: 225, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.2", text: "Фуры с боекомплектами. Основная колонна.", category: "Устав МО" },
    { id: 226, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.3", text: "Хаммер. Ведомый и завершающий колонну транспорт. В некоторых случаях разрешено не использовать замыкающий транспорт.", category: "Устав МО" },
    { id: 227, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.4", text: "Армейский Maverick. [Не обязательно].", category: "Устав МО" },
    { id: 228, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.5", text: "Запрещается обгон ведущей машины.", category: "Устав МО" },
    { id: 229, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.6", text: "Запрещается обгон фур.", category: "Устав МО" },
    { id: 230, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.7", text: "Передвижение колонны осуществляется только ровным строем и по одной полосе.", category: "Устав МО" },
    { id: 231, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.8", text: "Запрещено подрезать сопровождение от министерства юстиции.", category: "Устав МО" },
    { id: 232, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.8.1", text: "Запрещено подрезать гражданские авто, если гражданское авто угрожает колоне то фура/хаммер имеет право подрезать авто.", category: "Устав МО" },
    { id: 233, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4", text: "Задача хаммеров, вызвать вражеский огонь на себя. Путем прикрытия транспортом колонны.", category: "Устав МО" },
    { id: 234, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.1", text: "При нападении, конвой останавливается, выходит из машин и занимает круговую оборону, при помощи министерства юстиции. И при необходимости запрашивает подкрепление с базы.", category: "Устав МО" },
    { id: 235, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.2", text: "В критической ситуации, когда движение не может быть осуществлено, водители фур приступают к защите колонны.", category: "Устав МО" },
    { id: 236, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.3", text: "При уничтожении одной фуры, незамедлительно стоит поднять груз и загрузить в другую фуру.", category: "Устав МО" },
    { id: 237, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.4", text: "При транспортировке боеприпасов, обязательно иметь при себе оружие и рем. комплект.", category: "Устав МО" },
    { id: 238, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5", text: "Каждый боец несет ответственность за груз и сохранность транспорта.", category: "Устав МО" },
    { id: 239, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5.1", text: "Государственная [ПД] организация может предоставить транспорт и минимум двух человек для сопровождения.", category: "Устав МО" },
    { id: 240, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5.2", text: "Сопровождение от министерства юстиции не обязательно.", category: "Устав МО" },
    { id: 241, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5.6", text: "Если одному из депортаменов нужны срочно поставки, поставки может выполнить любая Армия. Вне зависимости от юриздикции.", category: "Устав МО" },
    { id: 242, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "6", text: "Распределение поставок среди МО в ПД. Армия г. Лос-Сантос: ЛСПД | РКШД. Армия г. Сан-Фиерро: ФБР | СФПД. Тюрьма Строгого Режима: РКШД | ЛВПД.", category: "Устав МО" },
    { id: 243, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "7", text: "Действия при нападении на колонну: 1. Выйти из машин и устранить угрозу. 2. В случае потери одной из машин во время нападения - продолжить движение (обязательно нужно иметь доказательства).", category: "Устав МО" },

    { id: 244, law: "Устав МО", chapter: "Курс офицерской подготовки [КОП]", point: "1", text: "Что необходимо знать и иметь при сдаче КОП: Знать Устав Министерства Обороны; Знать присягу [Cдается посредством биндера]; Иметь высокий уровень строевой подготовки; Иметь высокий уровень физической подготовки.", category: "Устав МО" },
    { id: 245, law: "Устав МО", chapter: "Курс офицерской подготовки [КОП]", point: "2", text: "Перечень испытаний, необходимых для сдачи КОП: Принятие присяги; Сдача устава Министерства Обороны [C уклоном на обязанности офицеров]; Сдача строевой подготовки; Сдача полосы препятствий [На учебном полигоне]; Десантирование на территорию своей базы; Заплыв; Экстремальное вождение.", category: "Устав МО" },
    { id: 246, law: "Устав МО", chapter: "Курс офицерской подготовки [КОП]", point: "3", text: "КОП принимает военнослужащий взвода ВОН. [ 5+ ранг ]. Сдающему нужно скринить каждый пункт сдачи испытания. Экзаменатор обязан писать в рацию после каждого испытания: /r [ Взвод ] Имя и Фамилия (сдающего) успешно сдал Название испытания. В конце сдачи КОП, экзаменатор обязан написать: /r [Взвод] Имя и Фамилия успешно сдал КОП.", category: "Устав МО" },

    { id: 247, law: "Устав МО", chapter: "Проведение лекций и тренировок", point: "1", text: "Критерии составления и прочтения лекций: Лекция должна разъяснять основные моменты службы в Министерстве обороны. Лекция должна доносить до военнослужащих информацию из уставных документов. Лекция должна побуждать интерес к теме доносимого. Лекция должна быть разумных объемов. [В зависимости от темы. Не нужно копировать устав целиком и полностью]. Лекция должна быть написана заранее и заучена. [Биндер]. Лекция должна читаться в нормальном темпе и разборчивым голосом. [Интервал между сообщениями в биндере - 5 секунд] [Несоблюдение этого правила будет наказываться выговором в личное дело]. Запрещено проведений лекций по рации [/r , /rb].", category: "Устав МО" },
    { id: 248, law: "Устав МО", chapter: "Проведение лекций и тренировок", point: "2", text: "Критерии составления и проведения тренировок: На тренировках разрешена отработка навыков стрельбы из пневматического оружия до снятия бронежилета. [системно /duel]. Тренировка может быть направлена на повышение военно-специальной подготовленности военнослужащих. Тренировка может быть направлена на совершенствование боевой слаженности воинских подразделений. Тренировка может быть направлена на развитие и совершенствование физических качеств. Тренировка должна способствовать воспитанию психической устойчивости и морально-волевых качеств; Тренировка не должна повлечь за собой нарушение действующих уставных документов Министерства Обороны со стороны военнослужащих. Тренировка должна иметь быть заранее спланированной и иметь отработанную форму проведения. [Не должна быть однотипной и банальной]. Минимальный интервал между обязательными построениями состава - 20 минут [исключения - ГРП и теракты].", category: "Устав МО" },

    { id: 249, law: "Устав МО", chapter: "Использование тегов в рации", point: "1", text: "В Организациях разрешены только тэги, устанавливаемые через команду /settag.", category: "Устав МО" },
    { id: 250, law: "Устав МО", chapter: "Использование тегов в рации", point: "2", text: "Тэги устанавливаются исключительно на русском языке.", category: "Устав МО" },
    { id: 251, law: "Устав МО", chapter: "Использование тегов в рации", point: "3", text: "Тэги устанавливаются по принципу принадлежности игрока взводу/отделу/подразделению и занимаемой им должности в этом взводе/отделе/подразделение.", category: "Устав МО" },
    { id: 252, law: "Устав МО", chapter: "Использование тегов в рации", point: "4", text: "Устанавливаемые тэги не должны противоречить РП процессу.", category: "Устав МО" },
    { id: 253, law: "Устав МО", chapter: "Использование тегов в рации", point: "5", text: "Запрещены тэги, в которых используется нецензурная лексика, либо которые могут кого либо оскорбить.", category: "Устав МО" },
    { id: 254, law: "Устав МО", chapter: "Использование тегов в рации", point: "6", text: "Следящая администрация вправе потребовать изменения/удаления определенных тэгов.", category: "Устав МО" },

    { id: 255, law: "Устав МО", chapter: "Территории военных баз", point: "1", text: "Сотрудникам гос структур/гражданам запрещено находится на Жёлтой зоне без предъявления документов военнослужащему армии по первой просьбе, в крайнем случае будет ликвидация данного человека.", category: "Устав МО" },
    { id: 256, law: "Устав МО", chapter: "Территории военных баз", point: "1.1", text: "Военнослужащий имеет полное право, увидев документ гражданина штата, попросить его отойти от КПП на 10 метров, для сохранения безопасности воинской части, в крайнем случае будет ликвидация данного человека.", category: "Устав МО" },
    { id: 257, law: "Устав МО", chapter: "Территории военных баз", point: "2", text: "Сотрудникам гос структур/гражданам запрещено находится на Красной зоне, даже при предъявлении документов военнослужащему армии, в этом случае военнослужащий имеет право на ликвидацию данного человека. Исключение: Сотрудники Министерства Юстиции в случае ЧС/запроса в департамент.", category: "Устав МО" },
    { id: 258, law: "Устав МО", chapter: "Территории военных баз", point: "3", text: "На Красной зоне имеют полное право находится сотрудники Министерства Юстиции, при Чрезвычайных ситуаций, при исполнении или задержании человека находящийся на данной территории.", category: "Устав МО" },
    { id: 259, law: "Устав МО", chapter: "Территории военных баз", point: "3.1", text: "Нахождения сотрудников Министерства Юстиции на территории объекта Министерства Обороны без причины - строго воспрещено!", category: "Устав МО" },
    { id: 260, law: "Устав МО", chapter: "Территории военных баз", point: "3.2", text: "Нахождение сотрудников Министерства Юстиции на территории объекта Министерства Обороны в маске запрещено. Разрешается в случае ЧС на объекте.", category: "Устав МО" },
    { id: 261, law: "Устав МО", chapter: "Территории военных баз", point: "3.3", text: "Сотрудник Министерства Юстиции обязан предъявить удостоверение любому военнослужащему Министерства Обороны. Любой военнослужащий имеет право спросить удостоверение только на КПП. На самой территории базы, только военнослужащий офицерского состава имеет право спросить удостоверение.", category: "Устав МО" },
    { id: 262, law: "Устав МО", chapter: "Территории военных баз", point: "3.4", text: "Облеты военных баз сотрудниками Министерства Юстиции, проводятся только с разрешения Офицерского состава Военной базы.", category: "Устав МО" },
    { id: 263, law: "Устав МО", chapter: "Территории военных баз", point: "3.5", text: "Доступ на территории военных баз сотрудники Министерства Юстиции без разрешения офицерского состава и проверки документов запрещён. Сотрудники SWAT и МЮ в целом имеют доступ на базу только в случае чрезвычайной ситуации и проверки военной базы на ЧС. Перед въездом на военную базу, сотрудники SWAT и МЮ обязаны предупредить об этом через волну департамента и запросить одобрение на въезд. Если сотрудник МЮ/SWAT выходит на связь с определённой армией и ему никто не отвечает, то ему запрещено самовольно проникать на территорию военной базы без одобрения офицерского состава армии.", category: "Устав МО" },
    { id: 264, law: "Устав МО", chapter: "Территории военных баз", point: "4", text: "Губернатор штата, Вице-Губернатор, а также их сопровождение имеют право находиться на территории любого военного объекта без особого разрешения, при предъявлении документов, согласно уставу Министерства Обороны.", category: "Устав МО" },
    { id: 265, law: "Устав МО", chapter: "Территории военных баз", point: "5", text: "Сотрудникам Государственных Структур запрещено находится на Красной зоне (исключение: пункт 3, 4).", category: "Устав МО" },
    { id: 266, law: "Устав МО", chapter: "Территории военных баз", point: "6", text: "Сотрудникам Министерства Здравоохранения разрешается нахождение на Красной зоне без предъявления документов военнослужащему армии, в случаем оказания Первой Медицинской Помощи. В остальных случаях посещения территории военных баз-обязаны предупредить об этом через волну департамента и запросить одобрение на въезд.", category: "Устав МО" },
    { id: 267, law: "Устав МО", chapter: "Территории военных баз", point: "7", text: "Данное правило действуют независимо на всех жителей Штата.", category: "Устав МО" },
    { id: 268, law: "Устав МО", chapter: "Территории военных баз", point: "8", text: "За нарушение данных правил гражданину/сотруднику гос. структуры полагается Уголовная ответственность.", category: "Устав МО" },
    { id: 269, law: "Устав МО", chapter: "Территории военных баз", point: "9", text: "За ликвидацию сотрудников гос. структур/гражданина находившиеся на Зелёной зоне без весомой причины военнослужащим данной армии, полагается наказанием (от выговора до jail 60-120)", category: "Устав МО" },
    { id: 270, law: "Устав МО", chapter: "Территории военных баз", point: "10", text: "За ликвидацию сотрудников гос. структур/гражданина находившиеся на Жёлтой зоне с предъявлением документов без весомой причины военнослужащим данной армии, полагается наказанием (от выговора до jail 60-120)", category: "Устав МО" },
    { id: 271, law: "Устав МО", chapter: "Территории военных баз", point: "11", text: "Военнослужащему запрещено требовать предъявления документов у лиц, находящихся исключительно в Зелёной зоне, если отсутствуют основания для проверки, предусмотренные настоящими правилами.", category: "Устав МО" },
    { id: 272, law: "Устав МО", chapter: "Территории военных баз", point: "12", text: "Любые изменения/нововведения в данное правило должно быть согласовано с руководством Министерства Обороны.", category: "Устав МО" },
    { id: 273, law: "Устав МО", chapter: "Территории военных баз", point: "12.1", text: "Любые изменения/нововведения в данное правило без согласования руководством Министерства Обороны, не является действительным.", category: "Устав МО" },
    { id: 274, law: "Устав МО", chapter: "Территории военных баз", point: "12.1.1", text: "На Оранжевой зоне запрещено находиться гражданским лицам и сотрудникам государственных структур без весомой причины. По требованию военнослужащего нарушитель обязан покинуть территорию. В случае отказа после установленного предупреждения военнослужащий вправе применить предусмотренные правилами меры для пресечения нарушения. Открытие огня допускается только при наличии оснований, предусмотренных Единым уставом МО.", category: "Устав МО" },
    { id: 275, law: "Устав МО", chapter: "Территории военных баз", point: "13", text: "В случае отказа покинуть территорию военкомата после трёх предупреждений военнослужащий вправе применить предусмотренные правилами меры для пресечения нарушения. Применение огнестрельного оружия допускается только при наличии оснований, предусмотренных Единым уставом МО. Действия военнослужащего должны быть зафиксированы на видеозапись. (с /time или включенной системной /bodycamera)", category: "Устав МО" },

    { id: 276, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "1", text: "Использовать личное Т/С разрешается только с ранга Подполковник/Контр-адмирал[8] в служебных целях.", category: "Устав МО" },
    { id: 277, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "2", text: "Служебными целями могут считаться: выезд в военкомат, поездки для подписания договоров/собрания/деловые встречи и т.п. (за бессмысленные катания по базе/карте последует наказание).", category: "Устав МО" },
    { id: 278, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "3", text: "Т/С военнослужащего должно выглядеть подобающе: строгая расцветка, отсутствие винилов, NonRP и ДБ-тюнинга (ковш, черепа, доски). Исключение: на авто может быть специальный кенгурятник.", category: "Устав МО" },
    { id: 279, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "3.1", text: "Разрешается использовать только легковое авто премиального класса. Пример: Mercedes, Cadillac, Rolls Royce, Maybach и т.д. Исключение: разрешение ГС/ЗГСа.", category: "Устав МО" },
    { id: 280, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "3.2", text: "Разрешены любые технические улучшения.", category: "Устав МО" },
    { id: 281, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "4", text: "Машина должна быть припаркована согласно уставу. За нарушение выше перечисленных пунктов лидер может получить балловое взыскание, при повторном нарушении - устное предупреждение.", category: "Устав МО" },

    { id: 282, law: "Устав МО", chapter: "Правила использования военных дронов", point: "1", text: "Военные дроны предназначены для патрулирования территории военной базы путем облета, защиты ее от нападения при помощи спусковой гранаты. Военный дрон не предназначен для вылета на нем за пределы территории базы, игр и веселья.", category: "Устав МО" },
    { id: 283, law: "Устав МО", chapter: "Правила использования военных дронов", point: "2", text: "За неправильное использование дронов предусмотрены следующие наказания: Убийство дроном без причины, помеха дроном, вылет дроном за пределы базы - JAIL на 120 минут. Последующее нарушение правил- WARN.", category: "Устав МО" },

    { id: 284, law: "Устав МО", chapter: "Примечания к правилам взаимодействия с Министерством Юстиции", point: "21.6", text: "В случае любого взаимодействия или задержания сотрудниками МЮ на территории военного объекта, военнослужащий обязан предоставить документ, удостоверяющий личность (паспорт), либо служебное удостоверение, чтобы официально доказать, что он является законным военнослужащим данной Армии или Тюрьмы Строгого Режима (ТСР). При уклонении от проверки документов сотрудники полиции вправе провести задержание до выяснения обстоятельства с последующим докладом руководству ВЧ.", category: "устав ТСР" }
];

window.tsrArticlesDB = tsrArticlesDB;